mapper.select:
select m.id, m.project_id, m.submit_time, m.contact_name, m.contact_phone, m.result_type, m.archive_dir, m.status, m.submit_status, m.guarantor_flag, m.guarantor_id, m.extra_data::text as extra_data, m.del_flag, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, p.project_name, p.project_code, p.engineering_project, p.project_location from proj_material m left join proj_project p on p.id = m.project_id where m.del_flag = '0'
and m.project_id = #{projectId}
and m.contact_name like concat('%', #{contactName}, '%')
and m.result_type = #{resultType}
and m.status = #{status}
and p.status in
#{s}
AND m.submit_status = #{submitStatus}
AND (m.contact_name like concat('%', #{keyword}, '%') or m.archive_dir like concat('%', #{keyword}, '%') or p.project_code like concat('%', #{keyword}, '%') or p.project_name like concat('%', #{keyword}, '%'))
AND m.submit_time >= #{submitTimeBegin}
AND m.submit_time <= #{submitTimeEnd}
AND m.contact_phone like concat('%', #{contactPhone}, '%')
AND p.project_code like concat('%', #{projectCode}, '%')
AND p.project_location like concat('%', #{projectLocation}, '%')
order by m.id desc

mapper.update:
update proj_material
project_id = #{projectId}, submit_time = #{submitTime}, contact_name = #{contactName}, contact_phone = #{contactPhone}, result_type = #{resultType}, archive_dir = #{archiveDir}, status = #{status}, submit_status = #{submitStatus}, guarantor_flag = #{guarantorFlag}, guarantor_id = null, guarantor_id = #{guarantorId}, extra_data = #{extraData}::jsonb, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}
